const ALL_AGENTS = ['codex', 'claude-code', 'copilot', 'cursor', 'gemini', 'generic'];

const readOnly = Object.freeze({
  filesystem: 'read',
  network: false,
  scripts: false,
  hooks: false,
  authentication: false,
});

function crux(id, name, category, description, instructions, options = {}) {
  return {
    id,
    name,
    category,
    description,
    kind: options.kind ?? 'skill',
    source: 'crux',
    status: options.status ?? 'recommended',
    agents: options.agents ?? ALL_AGENTS,
    permissions: options.permissions ?? readOnly,
    benefits: options.benefits ?? [description],
    useCases: options.useCases ?? [],
    instructions,
    tags: options.tags ?? [],
    required: options.required ?? false,
    explicitOnly: options.explicitOnly ?? false,
    tagline: options.tagline,
    documentation: options.documentation,
    diagram: options.diagram,
    intellectualProperty: options.intellectualProperty,
    version: options.version ?? '1.1.0',
    lastReviewed: options.lastReviewed ?? '2026-09-16',
    versionPolicy: options.versionPolicy ?? 'Detect the repository language, framework, runtime, and toolchain versions before applying guidance. Preserve supported project conventions, avoid deprecated APIs in new code, and propose migrations separately with compatibility and rollback notes.',
    references: options.references ?? [],
    license: 'MIT',
  };
}

function external(id, name, category, description, sourceUrl, options = {}) {
  return {
    id,
    name,
    category,
    description,
    kind: options.kind ?? 'skill',
    source: 'external',
    status: options.status ?? 'optional',
    agents: options.agents ?? ALL_AGENTS,
    permissions: options.permissions ?? readOnly,
    benefits: options.benefits ?? [description],
    useCases: options.useCases ?? [],
    tags: options.tags ?? [],
    sourceUrl,
    installCommand: options.installCommand,
    version: 'provider-managed',
    license: options.license ?? 'See provider',
  };
}

function technologyRules(id, name, description, instructions, references, tags = []) {
  return crux(id, name, 'Technology Rules', description, instructions, {
    kind: 'rule-pack',
    version: '1.1.0',
    tags: ['technology-rules', 'version-aware', ...tags],
    references,
  });
}

function accessibilityStandardRules(id, name, description, instructions, references, tags, versionPolicy) {
  return crux(id, name, 'Accessibility Standards', description, instructions, {
    kind: 'rule-pack',
    version: '1.1.0',
    tags: ['accessibility-standard', 'a11y', 'independently-selectable', ...tags],
    references,
    versionPolicy,
  });
}

